export const audioLabEnglish: readonly any[] = [
  {"id":"audio-eng01-security-basics", audioUrl: "/manus-storage/ep68-english-for-cyber-pros_bae9287d.wav","series":"english","title":"security-basics","description":"Vocabulário base de segurança","duration":"9min00s","topics":["inglês técnico","vocabulário de cibersegurança","breach","threat","vulnerability","asset","control","incident","malware","exploit","patch","compliance"],"transcript":[{"speaker":"Ana","text":"Welcome to the CyberDimension Audio Lab, Technical English series. Eu sou a Ana, e hoje praticamos inglês técnico para cibersegurança. O tema do episódio: Vocabulário base de segurança. Let's warm up with ten essential terms."},{"speaker":"Rafael","text":"Cada termo com pronúncia e exemplo, Ana. O primeiro da lista de hoje:"},{"speaker":"Ana","text":"Number one: \"breach\", pronounced \"bríitch\". In Brazilian Portuguese, we say \"violação, vazamento\". Example sentence: \"The company reported a data breach affecting customer records.\"."},{"speaker":"Rafael","text":"Repeating: \"breach\", \"The company reported a data breach affecting customer records.\". The pronunciation trick: O 'ea' soa como 'ii' longo.."},{"speaker":"Ana","text":"Number one: \"threat\", pronounced \"frét\". In Brazilian Portuguese, we say \"ameaça\". Example sentence: \"Phishing is one of the most common threats to employees.\"."},{"speaker":"Rafael","text":"Repeating: \"threat\", \"Phishing is one of the most common threats to employees.\". The pronunciation trick: O 'th' é o som dental, língua entre os dentes.."},{"speaker":"Ana","text":"Number one: \"vulnerability\", pronounced \"vâlnerabíliti\". In Brazilian Portuguese, we say \"vulnerabilidade\". Example sentence: \"The unpatched server had a critical vulnerability.\"."},{"speaker":"Rafael","text":"Repeating: \"vulnerability\", \"The unpatched server had a critical vulnerability.\". The pronunciation trick: Acento na sílaba 'bi'.."},{"speaker":"Ana","text":"Number one: \"asset\", pronounced \"éset\". In Brazilian Portuguese, we say \"ativo\". Example sentence: \"Every asset must be inventoried and classified.\"."},{"speaker":"Rafael","text":"Repeating: \"asset\", \"Every asset must be inventoried and classified.\". The pronunciation trick: Dois 's' com som de 's' simples.."},{"speaker":"Ana","text":"Number one: \"control\", pronounced \"kântrôul\". In Brazilian Portuguese, we say \"controle\". Example sentence: \"Encryption is a technical control that protects data.\"."},{"speaker":"Rafael","text":"Repeating: \"control\", \"Encryption is a technical control that protects data.\". The pronunciation trick: O 'o' final tem som de 'ôu'.."},{"speaker":"Ana","text":"Now the second half of our ten-term list:"},{"speaker":"Ana","text":"\"incident\", pronounced \"ínssedent\". We translate as \"incidente\". Example: \"The SOC team is investigating a security incident.\"."},{"speaker":"Rafael","text":"\"incident\". O 'c' duplo soa como 'ss'.."},{"speaker":"Ana","text":"\"malware\", pronounced \"méluer\". We translate as \"software malicioso\". Example: \"The antivirus detected malware on the endpoint.\"."},{"speaker":"Rafael","text":"\"malware\". Junção de 'malicious' + 'software'.."},{"speaker":"Ana","text":"\"exploit\", pronounced \"eksplóit\". We translate as \"explorar (vulnerabilidade)\". Example: \"Attackers used an exploit to gain admin access.\"."},{"speaker":"Rafael","text":"\"exploit\". Acento na segunda sílaba.."},{"speaker":"Ana","text":"\"patch\", pronounced \"pétch\". We translate as \"correção, atualização\". Example: \"Apply the security patch as soon as possible.\"."},{"speaker":"Rafael","text":"\"patch\". O 'tch' final como 'tch' de 'tchau'.."},{"speaker":"Ana","text":"\"compliance\", pronounced \"kâmpláians\". We translate as \"conformidade\". Example: \"The audit verified our compliance with the LGPD.\"."},{"speaker":"Rafael","text":"\"compliance\". O 'c' mudo não aparece na pronúncia.."},{"speaker":"Rafael","text":"Practice time, Ana. Ana, imagine o cenário: um analista de SOC descreve um incidente em inglês. 'We detected a breach caused by malware exploiting an unpatched vulnerability.' Que termos ele usou? — Usou 'breach', 'malware', 'exploit', 'unpatched' e 'vulnerability'. Cinco dos dez de hoje!"},{"speaker":"Ana","text":"Great dialog, Rafael. Remember: listen, repeat, and use the term in your next English conversation about security. The quiz checks your vocabulary, and the flashcards keep the terms in rotation. See you in the next Technical English episode of the Audio Lab!"}],"provenance":{"id":"audiolab-audio-eng01-security-basics","origin":"proprio","category":"Micro-learning em áudio (CyberDimension Audio Lab)","title":"Audio Lab — security-basics","source":"CyberDimension Academy","license":"Conteúdo autoral da CyberDimension Academy; uso de estudo dentro da plataforma.","usage":"Episódio de vocabulário técnico de cibersegurança em inglês, com pronúncia, tradução e exemplos autorais da CyberDimension Academy."}},
  {"id":"audio-eng02-networking", audioUrl: "/manus-storage/ep68-english-for-cyber-pros_bae9287d.wav","series":"english","title":"networking","description":"Networking vocabulary","duration":"9min00s","topics":["inglês técnico","vocabulário de cibersegurança","firewall","encryption","bandwidth","router","subnet","DNS","VPN","latency","packet","topology"],"transcript":[{"speaker":"Ana","text":"Welcome to the CyberDimension Audio Lab, Technical English series. Eu sou a Ana, e hoje praticamos inglês técnico para cibersegurança. O tema do episódio: Networking vocabulary. Let's warm up with ten essential terms."},{"speaker":"Rafael","text":"Cada termo com pronúncia e exemplo, Ana. O primeiro da lista de hoje:"},{"speaker":"Ana","text":"Number one: \"firewall\", pronounced \"fáiruól\". In Brazilian Portuguese, we say \"firewall, muro de fogo\". Example sentence: \"The firewall blocks unauthorized inbound traffic.\"."},{"speaker":"Rafael","text":"Repeating: \"firewall\", \"The firewall blocks unauthorized inbound traffic.\". The pronunciation trick: Palavra composta: fire + wall.."},{"speaker":"Ana","text":"Number one: \"encryption\", pronounced \"enkrípshon\". In Brazilian Portuguese, we say \"criptografia\". Example sentence: \"All traffic must use encryption in transit.\"."},{"speaker":"Rafael","text":"Repeating: \"encryption\", \"All traffic must use encryption in transit.\". The pronunciation trick: O 'c' inicial soa como 'k'.."},{"speaker":"Ana","text":"Number one: \"bandwidth\", pronounced \"bénduede\". In Brazilian Portuguese, we say \"largura de banda\". Example sentence: \"Low bandwidth slowed down the video analysis.\"."},{"speaker":"Rafael","text":"Repeating: \"bandwidth\", \"Low bandwidth slowed down the video analysis.\". The pronunciation trick: Acento na primeira sílaba.."},{"speaker":"Ana","text":"Number one: \"router\", pronounced \"ráuter\". In Brazilian Portuguese, we say \"roteador\". Example sentence: \"The router connects the internal network to the internet.\"."},{"speaker":"Rafael","text":"Repeating: \"router\", \"The router connects the internal network to the internet.\". The pronunciation trick: Soa como 'ráu-ter'.."},{"speaker":"Ana","text":"Number one: \"subnet\", pronounced \"sâbnet\". In Brazilian Portuguese, we say \"sub-rede\". Example sentence: \"The database lives in a separate subnet.\"."},{"speaker":"Rafael","text":"Repeating: \"subnet\", \"The database lives in a separate subnet.\". The pronunciation trick: O 'u' tem som de 'â'.."},{"speaker":"Ana","text":"Now the second half of our ten-term list:"},{"speaker":"Ana","text":"\"DNS\", pronounced \"di-en-és\". We translate as \"sistema de nomes de domínio\". Example: \"DNS hijacking redirects users to fake sites.\"."},{"speaker":"Rafael","text":"\"DNS\". Letreio em inglês: D-N-S.."},{"speaker":"Ana","text":"\"VPN\", pronounced \"vi-pi-én\". We translate as \"rede privada virtual\". Example: \"Remote workers connect through the corporate VPN.\"."},{"speaker":"Rafael","text":"\"VPN\". Letreio em inglês: V-P-N.."},{"speaker":"Ana","text":"\"latency\", pronounced \"léitensi\". We translate as \"latência\". Example: \"High latency affects real-time monitoring.\"."},{"speaker":"Rafael","text":"\"latency\". Acento na primeira sílaba.."},{"speaker":"Ana","text":"\"packet\", pronounced \"péket\". We translate as \"pacote\". Example: \"The packet sniffer captured the suspicious traffic.\"."},{"speaker":"Rafael","text":"\"packet\". O 'ck' soa como 'k'.."},{"speaker":"Ana","text":"\"topology\", pronounced \"topólodji\". We translate as \"topologia\". Example: \"The network topology uses a star design.\"."},{"speaker":"Rafael","text":"\"topology\". Acento em 'pó'.."},{"speaker":"Rafael","text":"Practice time, Ana. Diálogo de prática: 'The firewall detected an encrypted packet from an unknown subnet.' — 'Firewall', 'encrypted', 'packet' e 'subnet'. Quatro termos de rede no mesmo enunciado!"},{"speaker":"Ana","text":"Great dialog, Rafael. Remember: listen, repeat, and use the term in your next English conversation about security. The quiz checks your vocabulary, and the flashcards keep the terms in rotation. See you in the next Technical English episode of the Audio Lab!"}],"provenance":{"id":"audiolab-audio-eng02-networking","origin":"proprio","category":"Micro-learning em áudio (CyberDimension Audio Lab)","title":"Audio Lab — networking","source":"CyberDimension Academy","license":"Conteúdo autoral da CyberDimension Academy; uso de estudo dentro da plataforma.","usage":"Episódio de vocabulário técnico de cibersegurança em inglês, com pronúncia, tradução e exemplos autorais da CyberDimension Academy."}},
  {"id":"audio-eng03-soc-vocabulary", audioUrl: "/manus-storage/ep68-english-for-cyber-pros_bae9287d.wav","series":"english","title":"soc-vocabulary","description":"SOC vocabulary","duration":"9min00s","topics":["inglês técnico","vocabulário de cibersegurança","alert","triage","escalate","playbook","false positive","containment","evidence","shift","ticket","handover"],"transcript":[{"speaker":"Ana","text":"Welcome to the CyberDimension Audio Lab, Technical English series. Eu sou a Ana, e hoje praticamos inglês técnico para cibersegurança. O tema do episódio: SOC vocabulary. Let's warm up with ten essential terms."},{"speaker":"Rafael","text":"Cada termo com pronúncia e exemplo, Ana. O primeiro da lista de hoje:"},{"speaker":"Ana","text":"Number one: \"alert\", pronounced \"olért\". In Brazilian Portuguese, we say \"alerta\". Example sentence: \"The SIEM generated an alert for the failed logins.\"."},{"speaker":"Rafael","text":"Repeating: \"alert\", \"The SIEM generated an alert for the failed logins.\". The pronunciation trick: O 'al' inicial soa como 'ol'.."},{"speaker":"Ana","text":"Number one: \"triage\", pronounced \"triáj\". In Brazilian Portuguese, we say \"triagem\". Example sentence: \"Triage determines which alerts become incidents.\"."},{"speaker":"Rafael","text":"Repeating: \"triage\", \"Triage determines which alerts become incidents.\". The pronunciation trick: O 'g' final é mudo.."},{"speaker":"Ana","text":"Number one: \"escalate\", pronounced \"ésskaleit\". In Brazilian Portuguese, we say \"escalar\". Example sentence: \"Escalate the incident to the senior analyst.\"."},{"speaker":"Rafael","text":"Repeating: \"escalate\", \"Escalate the incident to the senior analyst.\". The pronunciation trick: Acento na primeira sílaba.."},{"speaker":"Ana","text":"Number one: \"playbook\", pronounced \"plêibuk\". In Brazilian Portuguese, we say \"manual de procedimentos\". Example sentence: \"Follow the playbook for ransomware response.\"."},{"speaker":"Rafael","text":"Repeating: \"playbook\", \"Follow the playbook for ransomware response.\". The pronunciation trick: Compound: play + book.."},{"speaker":"Ana","text":"Number one: \"false positive\", pronounced \"fóls pôzzitiv\". In Brazilian Portuguese, we say \"falso positivo\". Example sentence: \"The update scan was a false positive.\"."},{"speaker":"Rafael","text":"Repeating: \"false positive\", \"The update scan was a false positive.\". The pronunciation trick: Duas palavras, acento em 'fóls'.."},{"speaker":"Ana","text":"Now the second half of our ten-term list:"},{"speaker":"Ana","text":"\"containment\", pronounced \"kântêinment\". We translate as \"contenção\". Example: \"Containment stops the attack from spreading.\"."},{"speaker":"Rafael","text":"\"containment\". O 'tain' soa como 'têin'.."},{"speaker":"Ana","text":"\"evidence\", pronounced \"évidenss\". We translate as \"evidência\". Example: \"Preserve the evidence before investigating.\"."},{"speaker":"Rafael","text":"\"evidence\". O 'c' soa como 'ss'.."},{"speaker":"Ana","text":"\"shift\", pronounced \"xift\". We translate as \"plantão, turno\". Example: \"The night shift monitors the alerts.\"."},{"speaker":"Rafael","text":"\"shift\". O 'sh' soa como 'x'.."},{"speaker":"Ana","text":"\"ticket\", pronounced \"tíket\". We translate as \"chamado\". Example: \"Open a ticket for every confirmed incident.\"."},{"speaker":"Rafael","text":"\"ticket\". O 'ck' soa como 'k'.."},{"speaker":"Ana","text":"\"handover\", pronounced \"héndôuver\". We translate as \"passagem de plantão\". Example: \"The handover covers all open tickets.\"."},{"speaker":"Rafael","text":"\"handover\". O 'h' inicial é aspirado.."},{"speaker":"Rafael","text":"Practice time, Ana. Prática de plantão: 'During triage, I escalated a false positive and documented the evidence in the ticket.' — Triagem, escalonamento, falso positivo, evidência e chamado: cinco termos SOC em uma frase!"},{"speaker":"Ana","text":"Great dialog, Rafael. Remember: listen, repeat, and use the term in your next English conversation about security. The quiz checks your vocabulary, and the flashcards keep the terms in rotation. See you in the next Technical English episode of the Audio Lab!"}],"provenance":{"id":"audiolab-audio-eng03-soc-vocabulary","origin":"proprio","category":"Micro-learning em áudio (CyberDimension Audio Lab)","title":"Audio Lab — soc-vocabulary","source":"CyberDimension Academy","license":"Conteúdo autoral da CyberDimension Academy; uso de estudo dentro da plataforma.","usage":"Episódio de vocabulário técnico de cibersegurança em inglês, com pronúncia, tradução e exemplos autorais da CyberDimension Academy."}},
  {"id":"audio-eng04-incident-response", audioUrl: "/manus-storage/ep71-incident-response-interview_ae636a0e.wav","series":"english","title":"incident-response","description":"Como falar sobre incidentes","duration":"9min00s","topics":["inglês técnico","vocabulário de cibersegurança","breach notification","root cause","impact","scope","remediation","rollback","downtime","stakeholder","postmortem","lesson learned"],"transcript":[{"speaker":"Ana","text":"Welcome to the CyberDimension Audio Lab, Technical English series. Eu sou a Ana, e hoje praticamos inglês técnico para cibersegurança. O tema do episódio: Como falar sobre incidentes. Let's warm up with ten essential terms."},{"speaker":"Rafael","text":"Cada termo com pronúncia e exemplo, Ana. O primeiro da lista de hoje:"},{"speaker":"Ana","text":"Number one: \"breach notification\", pronounced \"bríitch notifiquêishon\". In Brazilian Portuguese, we say \"notificação de violação\". Example sentence: \"The breach notification was sent within 72 hours.\"."},{"speaker":"Rafael","text":"Repeating: \"breach notification\", \"The breach notification was sent within 72 hours.\". The pronunciation trick: 'tion' sempre soa como 'shon'.."},{"speaker":"Ana","text":"Number one: \"root cause\", pronounced \"rút kóz\". In Brazilian Portuguese, we say \"causa raiz\". Example sentence: \"The root cause was an unpatched web server.\"."},{"speaker":"Rafael","text":"Repeating: \"root cause\", \"The root cause was an unpatched web server.\". The pronunciation trick: Duas palavras, acentos em 'rút' e 'kóz'.."},{"speaker":"Ana","text":"Number one: \"impact\", pronounced \"ímpékt\". In Brazilian Portuguese, we say \"impacto\". Example sentence: \"The impact affected only the test environment.\"."},{"speaker":"Rafael","text":"Repeating: \"impact\", \"The impact affected only the test environment.\". The pronunciation trick: O 'p' final é suave.."},{"speaker":"Ana","text":"Number one: \"scope\", pronounced \"skôup\". In Brazilian Portuguese, we say \"escopo, alcance\". Example sentence: \"We are still defining the scope of the incident.\"."},{"speaker":"Rafael","text":"Repeating: \"scope\", \"We are still defining the scope of the incident.\". The pronunciation trick: O 'sc' soa como 'sk'.."},{"speaker":"Ana","text":"Number one: \"remediation\", pronounced \"remidêishon\". In Brazilian Portuguese, we say \"remediação\". Example sentence: \"Remediation includes patching and password resets.\"."},{"speaker":"Rafael","text":"Repeating: \"remediation\", \"Remediation includes patching and password resets.\". The pronunciation trick: 'tion' vira 'shon'.."},{"speaker":"Ana","text":"Now the second half of our ten-term list:"},{"speaker":"Ana","text":"\"rollback\", pronounced \"rôulbék\". We translate as \"reversão\". Example: \"The rollback restored the previous configuration.\"."},{"speaker":"Rafael","text":"\"rollback\". Compound: roll + back.."},{"speaker":"Ana","text":"\"downtime\", pronounced \"dáuntaim\". We translate as \"tempo de indisponibilidade\". Example: \"The downtime lasted about two hours.\"."},{"speaker":"Rafael","text":"\"downtime\". Compound: down + time.."},{"speaker":"Ana","text":"\"stakeholder\", pronounced \"stêikhôulder\". We translate as \"parte interessada\". Example: \"Stakeholders were informed every thirty minutes.\"."},{"speaker":"Rafael","text":"\"stakeholder\". Compound: stake + holder.."},{"speaker":"Ana","text":"\"postmortem\", pronounced \"pôustmórtrem\". We translate as \"análise pós-incidente\". Example: \"The postmortem meeting identified three improvements.\"."},{"speaker":"Rafael","text":"\"postmortem\". Do latim: após a morte do incidente.."},{"speaker":"Ana","text":"\"lesson learned\", pronounced \"lésson lérnd\". We translate as \"lição aprendida\". Example: \"Each lesson learned updates our playbook.\"."},{"speaker":"Rafael","text":"\"lesson learned\". 'ed' final soa como 'd'.."},{"speaker":"Rafael","text":"Practice time, Ana. Diálogo de status: 'The scope is limited, the root cause is identified, and remediation is in progress.' — Escopo, causa raiz e remediação: o trio clássico do update de incidente!"},{"speaker":"Ana","text":"Great dialog, Rafael. Remember: listen, repeat, and use the term in your next English conversation about security. The quiz checks your vocabulary, and the flashcards keep the terms in rotation. See you in the next Technical English episode of the Audio Lab!"}],"provenance":{"id":"audiolab-audio-eng04-incident-response","origin":"proprio","category":"Micro-learning em áudio (CyberDimension Audio Lab)","title":"Audio Lab — incident-response","source":"CyberDimension Academy","license":"Conteúdo autoral da CyberDimension Academy; uso de estudo dentro da plataforma.","usage":"Episódio de vocabulário técnico de cibersegurança em inglês, com pronúncia, tradução e exemplos autorais da CyberDimension Academy."}},
  {"id":"audio-eng05-cloud-vocabulary", audioUrl: "/manus-storage/ep70-cloud-security-interview_0daefd69.wav","series":"english","title":"cloud-vocabulary","description":"Cloud Security vocabulary","duration":"9min00s","topics":["inglês técnico","vocabulário de cibersegurança","shared responsibility","IAM","bucket","misconfiguration","availability zone","container","serverless","encryption at rest","encryption in transit","least privilege"],"transcript":[{"speaker":"Ana","text":"Welcome to the CyberDimension Audio Lab, Technical English series. Eu sou a Ana, e hoje praticamos inglês técnico para cibersegurança. O tema do episódio: Cloud Security vocabulary. Let's warm up with ten essential terms."},{"speaker":"Rafael","text":"Cada termo com pronúncia e exemplo, Ana. O primeiro da lista de hoje:"},{"speaker":"Ana","text":"Number one: \"shared responsibility\", pronounced \"xérd rispânsabíliti\". In Brazilian Portuguese, we say \"responsabilidade compartilhada\". Example sentence: \"Cloud security follows the shared responsibility model.\"."},{"speaker":"Rafael","text":"Repeating: \"shared responsibility\", \"Cloud security follows the shared responsibility model.\". The pronunciation trick: Acento de 'shared' em 'xérd'.."},{"speaker":"Ana","text":"Number one: \"IAM\", pronounced \"ái-éi-ém\". In Brazilian Portuguese, we say \"gestão de identidade e acesso\". Example sentence: \"IAM policies define who can access each resource.\"."},{"speaker":"Rafael","text":"Repeating: \"IAM\", \"IAM policies define who can access each resource.\". The pronunciation trick: Letreio em inglês: I-A-M.."},{"speaker":"Ana","text":"Number one: \"bucket\", pronounced \"bâket\". In Brazilian Portuguese, we say \"bucket, repositório\". Example sentence: \"The S3 bucket was publicly accessible by mistake.\"."},{"speaker":"Rafael","text":"Repeating: \"bucket\", \"The S3 bucket was publicly accessible by mistake.\". The pronunciation trick: O 'u' soa como 'â'.."},{"speaker":"Ana","text":"Number one: \"misconfiguration\", pronounced \"misconfiâgurêishon\". In Brazilian Portuguese, we say \"configuração incorreta\". Example sentence: \"Misconfiguration is a leading cloud risk.\"."},{"speaker":"Rafael","text":"Repeating: \"misconfiguration\", \"Misconfiguration is a leading cloud risk.\". The pronunciation trick: 'tion' vira 'shon'.."},{"speaker":"Ana","text":"Number one: \"availability zone\", pronounced \"aveilabíliti zôn\". In Brazilian Portuguese, we say \"zona de disponibilidade\". Example sentence: \"Deploy replicas across availability zones.\"."},{"speaker":"Rafael","text":"Repeating: \"availability zone\", \"Deploy replicas across availability zones.\". The pronunciation trick: Acentos em 'vei' e 'zôn'.."},{"speaker":"Ana","text":"Now the second half of our ten-term list:"},{"speaker":"Ana","text":"\"container\", pronounced \"kântêiner\". We translate as \"contêiner\". Example: \"Scan containers before deploying to production.\"."},{"speaker":"Rafael","text":"\"container\". Acento em 'têin'.."},{"speaker":"Ana","text":"\"serverless\", pronounced \"sérverless\". We translate as \"sem servidor (gerenciado)\". Example: \"Serverless functions scale automatically.\"."},{"speaker":"Rafael","text":"\"serverless\". O 'less' final é leve.."},{"speaker":"Ana","text":"\"encryption at rest\", pronounced \"enkrípshon ét rést\". We translate as \"criptografia em repouso\". Example: \"Enable encryption at rest for all storage.\"."},{"speaker":"Rafael","text":"\"encryption at rest\". Três palavras, ritmo constante.."},{"speaker":"Ana","text":"\"encryption in transit\", pronounced \"enkrípshon in trânzit\". We translate as \"criptografia em trânsito\". Example: \"Traffic uses encryption in transit via TLS.\"."},{"speaker":"Rafael","text":"\"encryption in transit\". 'transit' com 'z' suave.."},{"speaker":"Ana","text":"\"least privilege\", pronounced \"líist prívilidj\". We translate as \"privilégio mínimo\". Example: \"Assign least privilege to every service account.\"."},{"speaker":"Rafael","text":"\"least privilege\". Acentos em 'líist' e 'prí'.."},{"speaker":"Rafael","text":"Practice time, Ana. Frase de arquitetura: 'The bucket misconfiguration violated least privilege; encryption at rest and in transit are now enforced.' — Cinco termos de nuvem, uma frase completa!"},{"speaker":"Ana","text":"Great dialog, Rafael. Remember: listen, repeat, and use the term in your next English conversation about security. The quiz checks your vocabulary, and the flashcards keep the terms in rotation. See you in the next Technical English episode of the Audio Lab!"}],"provenance":{"id":"audiolab-audio-eng05-cloud-vocabulary","origin":"proprio","category":"Micro-learning em áudio (CyberDimension Audio Lab)","title":"Audio Lab — cloud-vocabulary","source":"CyberDimension Academy","license":"Conteúdo autoral da CyberDimension Academy; uso de estudo dentro da plataforma.","usage":"Episódio de vocabulário técnico de cibersegurança em inglês, com pronúncia, tradução e exemplos autorais da CyberDimension Academy."}},
  {"id":"audio-eng06-pentest-vocabulary", audioUrl: "/manus-storage/ep72-penetration-testing-interview_6def4bcb.wav","series":"english","title":"pentest-vocabulary","description":"Pentesting vocabulary","duration":"9min00s","topics":["inglês técnico","vocabulário de cibersegurança","reconnaissance","enumeration","payload","shell","privilege escalation","scope of work","authorization","report","finding","remediate"],"transcript":[{"speaker":"Ana","text":"Welcome to the CyberDimension Audio Lab, Technical English series. Eu sou a Ana, e hoje praticamos inglês técnico para cibersegurança. O tema do episódio: Pentesting vocabulary. Let's warm up with ten essential terms."},{"speaker":"Rafael","text":"Cada termo com pronúncia e exemplo, Ana. O primeiro da lista de hoje:"},{"speaker":"Ana","text":"Number one: \"reconnaissance\", pronounced \"rekânerâns\". In Brazilian Portuguese, we say \"reconhecimento\". Example sentence: \"Reconnaissance maps the target before any test.\"."},{"speaker":"Rafael","text":"Repeating: \"reconnaissance\", \"Reconnaissance maps the target before any test.\". The pronunciation trick: A palavra francesa adaptada: ritmo em quatro sílabas.."},{"speaker":"Ana","text":"Number one: \"enumeration\", pronounced \"inâmiurêishon\". In Brazilian Portuguese, we say \"enumeração\". Example sentence: \"Enumeration lists users, shares and services.\"."},{"speaker":"Rafael","text":"Repeating: \"enumeration\", \"Enumeration lists users, shares and services.\". The pronunciation trick: 'tion' vira 'shon'.."},{"speaker":"Ana","text":"Number one: \"payload\", pronounced \"pêilôud\". In Brazilian Portuguese, we say \"carga maliciosa\". Example sentence: \"The payload executes after the exploit succeeds.\"."},{"speaker":"Rafael","text":"Repeating: \"payload\", \"The payload executes after the exploit succeeds.\". The pronunciation trick: Compound: pay + load.."},{"speaker":"Ana","text":"Number one: \"shell\", pronounced \"xél\". In Brazilian Portuguese, we say \"shell, acesso remoto\". Example sentence: \"The pentester obtained a reverse shell.\"."},{"speaker":"Rafael","text":"Repeating: \"shell\", \"The pentester obtained a reverse shell.\". The pronunciation trick: O 'sh' soa como 'x'.."},{"speaker":"Ana","text":"Number one: \"privilege escalation\", pronounced \"prívilidj ésskaleishon\". In Brazilian Portuguese, we say \"elevação de privilégio\". Example sentence: \"Privilege escalation turns user access into admin access.\"."},{"speaker":"Rafael","text":"Repeating: \"privilege escalation\", \"Privilege escalation turns user access into admin access.\". The pronunciation trick: Duas palavras técnicas.."},{"speaker":"Ana","text":"Now the second half of our ten-term list:"},{"speaker":"Ana","text":"\"scope of work\", pronounced \"skôup ôv uérk\". We translate as \"escopo do trabalho\". Example: \"The scope of work defines authorized targets.\"."},{"speaker":"Rafael","text":"\"scope of work\". Ritmo em três palavras.."},{"speaker":"Ana","text":"\"authorization\", pronounced \"ózerêishon\". We translate as \"autorização\". Example: \"Written authorization is required before testing.\"."},{"speaker":"Rafael","text":"\"authorization\". O 'z' soa como 'z' americano.."},{"speaker":"Ana","text":"\"report\", pronounced \"riport\". We translate as \"relatório\". Example: \"The report includes findings and recommendations.\"."},{"speaker":"Rafael","text":"\"report\". O 'r' final é suave.."},{"speaker":"Ana","text":"\"finding\", pronounced \"fáindin\". We translate as \"achado, vulnerabilidade encontrada\". Example: \"Each finding receives a severity rating.\"."},{"speaker":"Rafael","text":"\"finding\". Do verbo 'to find'.."},{"speaker":"Ana","text":"\"remediate\", pronounced \"remidêit\". We translate as \"remediar\". Example: \"The team must remediate the critical findings.\"."},{"speaker":"Rafael","text":"\"remediate\". Acento em 'mêi'.."},{"speaker":"Rafael","text":"Practice time, Ana. Diálogo de pentester: 'After reconnaissance and enumeration, the payload delivered a shell, but privilege escalation stayed out of scope.' — Seis termos em um relatório!"},{"speaker":"Ana","text":"Great dialog, Rafael. Remember: listen, repeat, and use the term in your next English conversation about security. The quiz checks your vocabulary, and the flashcards keep the terms in rotation. See you in the next Technical English episode of the Audio Lab!"}],"provenance":{"id":"audiolab-audio-eng06-pentest-vocabulary","origin":"proprio","category":"Micro-learning em áudio (CyberDimension Audio Lab)","title":"Audio Lab — pentest-vocabulary","source":"CyberDimension Academy","license":"Conteúdo autoral da CyberDimension Academy; uso de estudo dentro da plataforma.","usage":"Episódio de vocabulário técnico de cibersegurança em inglês, com pronúncia, tradução e exemplos autorais da CyberDimension Academy."}},
  {"id":"audio-eng07-grc-english", audioUrl: "/manus-storage/ep20-governanca-risco_d7215fc4.wav","series":"english","title":"grc-english","description":"GRC vocabulary","duration":"9min00s","topics":["inglês técnico","vocabulário de cibersegurança","governance","risk assessment","framework","control","audit","compliance","policy","stakeholder","third party","due diligence"],"transcript":[{"speaker":"Ana","text":"Welcome to the CyberDimension Audio Lab, Technical English series. Eu sou a Ana, e hoje praticamos inglês técnico para cibersegurança. O tema do episódio: GRC vocabulary. Let's warm up with ten essential terms."},{"speaker":"Rafael","text":"Cada termo com pronúncia e exemplo, Ana. O primeiro da lista de hoje:"},{"speaker":"Ana","text":"Number one: \"governance\", pronounced \"gâvernenss\". In Brazilian Portuguese, we say \"governança\". Example sentence: \"Security governance starts at the board level.\"."},{"speaker":"Rafael","text":"Repeating: \"governance\", \"Security governance starts at the board level.\". The pronunciation trick: O 'c' soa como 'ss'.."},{"speaker":"Ana","text":"Number one: \"risk assessment\", pronounced \"rísk aséssment\". In Brazilian Portuguese, we say \"avaliação de risco\". Example sentence: \"The annual risk assessment updates our priorities.\"."},{"speaker":"Rafael","text":"Repeating: \"risk assessment\", \"The annual risk assessment updates our priorities.\". The pronunciation trick: Duas palavras, acentos claros.."},{"speaker":"Ana","text":"Number one: \"framework\", pronounced \"frêimuérk\". In Brazilian Portuguese, we say \"framework, estrutura\". Example sentence: \"We adopted the NIST framework for controls.\"."},{"speaker":"Rafael","text":"Repeating: \"framework\", \"We adopted the NIST framework for controls.\". The pronunciation trick: Compound: frame + work.."},{"speaker":"Ana","text":"Number one: \"control\", pronounced \"kântrôul\". In Brazilian Portuguese, we say \"controle\". Example sentence: \"Access control reduces insider risk.\"."},{"speaker":"Rafael","text":"Repeating: \"control\", \"Access control reduces insider risk.\". The pronunciation trick: O 'o' final como 'ôu'.."},{"speaker":"Ana","text":"Number one: \"audit\", pronounced \"ódit\". In Brazilian Portuguese, we say \"auditoria\". Example sentence: \"The external audit verified our ISO certification.\"."},{"speaker":"Rafael","text":"Repeating: \"audit\", \"The external audit verified our ISO certification.\". The pronunciation trick: O 'u' é mudo.."},{"speaker":"Ana","text":"Now the second half of our ten-term list:"},{"speaker":"Ana","text":"\"compliance\", pronounced \"kâmpláians\". We translate as \"conformidade\". Example: \"LGPD compliance requires documented consent.\"."},{"speaker":"Rafael","text":"\"compliance\". O 'c' mudo.."},{"speaker":"Ana","text":"\"policy\", pronounced \"pólissi\". We translate as \"política\". Example: \"The acceptable use policy covers personal devices.\"."},{"speaker":"Rafael","text":"\"policy\". O 'y' final soa como 'i'.."},{"speaker":"Ana","text":"\"stakeholder\", pronounced \"stêikhôulder\". We translate as \"parte interessada\". Example: \"Stakeholders approved the risk acceptance.\"."},{"speaker":"Rafael","text":"\"stakeholder\". Três sílabas, 'hôul' alongado.."},{"speaker":"Ana","text":"\"third party\", pronounced \"thérd párti\". We translate as \"terceiro\". Example: \"Third-party risk is assessed before contracting.\"."},{"speaker":"Rafael","text":"\"third party\". O 'th' dental.."},{"speaker":"Ana","text":"\"due diligence\", pronounced \"diú dílidjenss\". We translate as \"diligência prévia\". Example: \"Due diligence reviews precede every acquisition.\"."},{"speaker":"Rafael","text":"\"due diligence\". Expressão francesa, dois acentos.."},{"speaker":"Rafael","text":"Practice time, Ana. Frase de governança: 'The governance framework requires an annual risk assessment, audit evidence and third-party due diligence.' — Cinco termos GRC na mesma frase!"},{"speaker":"Ana","text":"Great dialog, Rafael. Remember: listen, repeat, and use the term in your next English conversation about security. The quiz checks your vocabulary, and the flashcards keep the terms in rotation. See you in the next Technical English episode of the Audio Lab!"}],"provenance":{"id":"audiolab-audio-eng07-grc-english","origin":"proprio","category":"Micro-learning em áudio (CyberDimension Audio Lab)","title":"Audio Lab — grc-english","source":"CyberDimension Academy","license":"Conteúdo autoral da CyberDimension Academy; uso de estudo dentro da plataforma.","usage":"Episódio de vocabulário técnico de cibersegurança em inglês, com pronúncia, tradução e exemplos autorais da CyberDimension Academy."}},
  {"id":"audio-eng08-interview-english", audioUrl: "/manus-storage/ep69-network-security-interview_54014d2f.wav","series":"english","title":"interview-english","description":"Interview English: presenting yourself","duration":"9min00s","topics":["inglês técnico","vocabulário de cibersegurança","background","strengths","achievement","responsibility","teamwork","deadline","feedback","challenge","goal","certification"],"transcript":[{"speaker":"Ana","text":"Welcome to the CyberDimension Audio Lab, Technical English series. Eu sou a Ana, e hoje praticamos inglês técnico para cibersegurança. O tema do episódio: Interview English: presenting yourself. Let's warm up with ten essential terms."},{"speaker":"Rafael","text":"Cada termo com pronúncia e exemplo, Ana. O primeiro da lista de hoje:"},{"speaker":"Ana","text":"Number one: \"background\", pronounced \"békgraund\". In Brazilian Portuguese, we say \"experiência, histórico\". Example sentence: \"My background includes three years in SOC operations.\"."},{"speaker":"Rafael","text":"Repeating: \"background\", \"My background includes three years in SOC operations.\". The pronunciation trick: Compound: back + ground.."},{"speaker":"Ana","text":"Number one: \"strengths\", pronounced \"strénths\". In Brazilian Portuguese, we say \"pontos fortes\". Example sentence: \"My strengths are log analysis and incident triage.\"."},{"speaker":"Rafael","text":"Repeating: \"strengths\", \"My strengths are log analysis and incident triage.\". The pronunciation trick: O 'ngths' é desafiador: 'nths'.."},{"speaker":"Ana","text":"Number one: \"achievement\", pronounced \"atchívment\". In Brazilian Portuguese, we say \"conquista\". Example sentence: \"My key achievement was reducing alert fatigue by forty percent.\"."},{"speaker":"Rafael","text":"Repeating: \"achievement\", \"My key achievement was reducing alert fatigue by forty percent.\". The pronunciation trick: O 'ch' soa como 'tch'.."},{"speaker":"Ana","text":"Number one: \"responsibility\", pronounced \"rispânsabíliti\". In Brazilian Portuguese, we say \"responsabilidade\". Example sentence: \"My main responsibility was monitoring critical assets.\"."},{"speaker":"Rafael","text":"Repeating: \"responsibility\", \"My main responsibility was monitoring critical assets.\". The pronunciation trick: Ritmo longo, acento em 'bi'.."},{"speaker":"Ana","text":"Number one: \"teamwork\", pronounced \"tímuérk\". In Brazilian Portuguese, we say \"trabalho em equipe\". Example sentence: \"I value teamwork in incident response.\"."},{"speaker":"Rafael","text":"Repeating: \"teamwork\", \"I value teamwork in incident response.\". The pronunciation trick: Compound: team + work.."},{"speaker":"Ana","text":"Now the second half of our ten-term list:"},{"speaker":"Ana","text":"\"deadline\", pronounced \"dédlain\". We translate as \"prazo\". Example: \"We delivered the report before the deadline.\"."},{"speaker":"Rafael","text":"\"deadline\". Compound: dead + line.."},{"speaker":"Ana","text":"\"feedback\", pronounced \"fídbék\". We translate as \"retorno, feedback\". Example: \"I actively ask for feedback to improve.\"."},{"speaker":"Rafael","text":"\"feedback\". Compound: feed + back.."},{"speaker":"Ana","text":"\"challenge\", pronounced \"tchálenj\". We translate as \"desafio\". Example: \"The biggest challenge was the ransomware incident.\"."},{"speaker":"Rafael","text":"\"challenge\". O 'ch' como 'tch'.."},{"speaker":"Ana","text":"\"goal\", pronounced \"gôul\". We translate as \"meta, objetivo\". Example: \"My short-term goal is the Security+ certification.\"."},{"speaker":"Rafael","text":"\"goal\". O 'oa' vira 'ôu'.."},{"speaker":"Ana","text":"\"certification\", pronounced \"sértifiquêishon\". We translate as \"certificação\". Example: \"This certification validates my Security+ knowledge.\"."},{"speaker":"Rafael","text":"\"certification\". 'tion' vira 'shon'.."},{"speaker":"Rafael","text":"Practice time, Ana. Pitch de entrevista: 'With a three-year background in SOC, my strengths are triage and analysis, and my next goal is the Security+ certification.' — Background, strengths e goal em uma apresentação!"},{"speaker":"Ana","text":"Great dialog, Rafael. Remember: listen, repeat, and use the term in your next English conversation about security. The quiz checks your vocabulary, and the flashcards keep the terms in rotation. See you in the next Technical English episode of the Audio Lab!"}],"provenance":{"id":"audiolab-audio-eng08-interview-english","origin":"proprio","category":"Micro-learning em áudio (CyberDimension Audio Lab)","title":"Audio Lab — interview-english","source":"CyberDimension Academy","license":"Conteúdo autoral da CyberDimension Academy; uso de estudo dentro da plataforma.","usage":"Episódio de vocabulário técnico de cibersegurança em inglês, com pronúncia, tradução e exemplos autorais da CyberDimension Academy."}},
  {"id":"audio-eng09-explaining-vulnerability", audioUrl: "/manus-storage/ep69-network-security-interview_54014d2f.wav","series":"english","title":"explaining-vulnerability","description":"Como explicar uma vulnerabilidade em inglês","duration":"9min00s","topics":["inglês técnico","vocabulário de cibersegurança","flaw","unauthorized","severity","patch","workaround","exposure","mitigation","affected","proof of concept","responsible disclosure"],"transcript":[{"speaker":"Ana","text":"Welcome to the CyberDimension Audio Lab, Technical English series. Eu sou a Ana, e hoje praticamos inglês técnico para cibersegurança. O tema do episódio: Como explicar uma vulnerabilidade em inglês. Let's warm up with ten essential terms."},{"speaker":"Rafael","text":"Cada termo com pronúncia e exemplo, Ana. O primeiro da lista de hoje:"},{"speaker":"Ana","text":"Number one: \"flaw\", pronounced \"flóu\". In Brazilian Portuguese, we say \"falha\". Example sentence: \"The flaw allowed unauthenticated access.\"."},{"speaker":"Rafael","text":"Repeating: \"flaw\", \"The flaw allowed unauthenticated access.\". The pronunciation trick: O 'aw' soa como 'ôu'.."},{"speaker":"Ana","text":"Number one: \"unauthorized\", pronounced \"anózeráizd\". In Brazilian Portuguese, we say \"não autorizado\". Example sentence: \"The attacker gained unauthorized access to the database.\"."},{"speaker":"Rafael","text":"Repeating: \"unauthorized\", \"The attacker gained unauthorized access to the database.\". The pronunciation trick: Quatro sílabas, acento em 'zêi'.."},{"speaker":"Ana","text":"Number one: \"severity\", pronounced \"sivérati\". In Brazilian Portuguese, we say \"severidade\". Example sentence: \"The CVSS score defines the severity level.\"."},{"speaker":"Rafael","text":"Repeating: \"severity\", \"The CVSS score defines the severity level.\". The pronunciation trick: Acento em 'vé'.."},{"speaker":"Ana","text":"Number one: \"patch\", pronounced \"pétch\". In Brazilian Portuguese, we say \"correção\". Example sentence: \"A patch is available since last week.\"."},{"speaker":"Rafael","text":"Repeating: \"patch\", \"A patch is available since last week.\". The pronunciation trick: O 'tch' como em 'tchau'.."},{"speaker":"Ana","text":"Number one: \"workaround\", pronounced \"uérkraund\". In Brazilian Portuguese, we say \"solução temporária\". Example sentence: \"The workaround limits exposure until the patch.\"."},{"speaker":"Rafael","text":"Repeating: \"workaround\", \"The workaround limits exposure until the patch.\". The pronunciation trick: Compound: work + around.."},{"speaker":"Ana","text":"Now the second half of our ten-term list:"},{"speaker":"Ana","text":"\"exposure\", pronounced \"ekspôuzher\". We translate as \"exposição\". Example: \"The exposure affected external-facing services.\"."},{"speaker":"Rafael","text":"\"exposure\". O 'sure' soa como 'jer'.."},{"speaker":"Ana","text":"\"mitigation\", pronounced \"mitigêishon\". We translate as \"mitigação\". Example: \"Our mitigation includes segmentation and monitoring.\"."},{"speaker":"Rafael","text":"\"mitigation\". 'tion' vira 'shon'.."},{"speaker":"Ana","text":"\"affected\", pronounced \"afékted\". We translate as \"afetado\". Example: \"Only two systems were affected by the flaw.\"."},{"speaker":"Rafael","text":"\"affected\". O 'ed' final como 't'.."},{"speaker":"Ana","text":"\"proof of concept\", pronounced \"prúuf ôv kónsept\". We translate as \"prova de conceito\". Example: \"The researcher published a proof of concept.\"."},{"speaker":"Rafael","text":"\"proof of concept\". Três palavras, ritmo em 'prúuf'.."},{"speaker":"Ana","text":"\"responsible disclosure\", pronounced \"rispónssibel disklôuzher\". We translate as \"divulgação responsável\". Example: \"We follow responsible disclosure with vendors.\"."},{"speaker":"Rafael","text":"\"responsible disclosure\". O 'sure' como 'jer'.."},{"speaker":"Rafael","text":"Practice time, Ana. Explicação ao time: 'This flaw has high severity; the mitigation is a patch, with a workaround to limit exposure meanwhile.' — Flaw, severity, mitigation, patch, exposure e workaround!"},{"speaker":"Ana","text":"Great dialog, Rafael. Remember: listen, repeat, and use the term in your next English conversation about security. The quiz checks your vocabulary, and the flashcards keep the terms in rotation. See you in the next Technical English episode of the Audio Lab!"}],"provenance":{"id":"audiolab-audio-eng09-explaining-vulnerability","origin":"proprio","category":"Micro-learning em áudio (CyberDimension Audio Lab)","title":"Audio Lab — explaining-vulnerability","source":"CyberDimension Academy","license":"Conteúdo autoral da CyberDimension Academy; uso de estudo dentro da plataforma.","usage":"Episódio de vocabulário técnico de cibersegurança em inglês, com pronúncia, tradução e exemplos autorais da CyberDimension Academy."}},
  {"id":"audio-eng10-presenting-project", audioUrl: "/manus-storage/ep69-network-security-interview_54014d2f.wav","series":"english","title":"presenting-project","description":"Como apresentar um projeto de segurança","duration":"9min00s","topics":["inglês técnico","vocabulário de cibersegurança","objective","scope","budget","timeline","milestone","stakeholder","deliverable","metric","roi","roadmap"],"transcript":[{"speaker":"Ana","text":"Welcome to the CyberDimension Audio Lab, Technical English series. Eu sou a Ana, e hoje praticamos inglês técnico para cibersegurança. O tema do episódio: Como apresentar um projeto de segurança. Let's warm up with ten essential terms."},{"speaker":"Rafael","text":"Cada termo com pronúncia e exemplo, Ana. O primeiro da lista de hoje:"},{"speaker":"Ana","text":"Number one: \"objective\", pronounced \"objétiv\". In Brazilian Portuguese, we say \"objetivo\". Example sentence: \"The project objective is to reduce phishing success rates.\"."},{"speaker":"Rafael","text":"Repeating: \"objective\", \"The project objective is to reduce phishing success rates.\". The pronunciation trick: Acento em 'je'.."},{"speaker":"Ana","text":"Number one: \"scope\", pronounced \"skôup\". In Brazilian Portuguese, we say \"escopo\". Example sentence: \"The scope covers all internal applications.\"."},{"speaker":"Rafael","text":"Repeating: \"scope\", \"The scope covers all internal applications.\". The pronunciation trick: O 'sc' como 'sk'.."},{"speaker":"Ana","text":"Number one: \"budget\", pronounced \"bâdjêt\". In Brazilian Portuguese, we say \"orçamento\". Example sentence: \"The budget includes tools, training and consulting.\"."},{"speaker":"Rafael","text":"Repeating: \"budget\", \"The budget includes tools, training and consulting.\". The pronunciation trick: O 'dg' soa como 'dj'.."},{"speaker":"Ana","text":"Number one: \"timeline\", pronounced \"táimlain\". In Brazilian Portuguese, we say \"cronograma\". Example sentence: \"The timeline spans two quarters.\"."},{"speaker":"Rafael","text":"Repeating: \"timeline\", \"The timeline spans two quarters.\". The pronunciation trick: Compound: time + line.."},{"speaker":"Ana","text":"Number one: \"milestone\", pronounced \"máilstoun\". In Brazilian Portuguese, we say \"marco\". Example sentence: \"We reached the first milestone ahead of schedule.\"."},{"speaker":"Rafael","text":"Repeating: \"milestone\", \"We reached the first milestone ahead of schedule.\". The pronunciation trick: O 'stone' soa como 'stoun'.."},{"speaker":"Ana","text":"Now the second half of our ten-term list:"},{"speaker":"Ana","text":"\"stakeholder\", pronounced \"stêikhôulder\". We translate as \"parte interessada\". Example: \"Stakeholders approved the security initiative.\"."},{"speaker":"Rafael","text":"\"stakeholder\". Três sílabas com 'hôul' alongado.."},{"speaker":"Ana","text":"\"deliverable\", pronounced \"dilíverebel\". We translate as \"entregável\". Example: \"The security awareness report is our main deliverable.\"."},{"speaker":"Rafael","text":"\"deliverable\". Acento em 've' e 'be' leves.."},{"speaker":"Ana","text":"\"metric\", pronounced \"métrik\". We translate as \"métrica\". Example: \"The key metric is the reduction in click rates.\"."},{"speaker":"Rafael","text":"\"metric\". O 'c' final soa como 'k'.."},{"speaker":"Ana","text":"\"roi\", pronounced \"ár-ou-ái\". We translate as \"retorno sobre investimento\". Example: \"The roi justifies the new security tooling.\"."},{"speaker":"Rafael","text":"\"roi\". Letreio em inglês: R-O-I.."},{"speaker":"Ana","text":"\"roadmap\", pronounced \"rôudmép\". We translate as \"roteiro estratégico\". Example: \"The security roadmap covers the next eighteen months.\"."},{"speaker":"Rafael","text":"\"roadmap\". Compound: road + map.."},{"speaker":"Rafael","text":"Practice time, Ana. Pitch de projeto: 'The objective is phishing reduction, the scope covers internal apps, the timeline has two milestones, and the roi is positive.' — Objetivo, escopo, cronograma, marcos e roi!"},{"speaker":"Ana","text":"Great dialog, Rafael. Remember: listen, repeat, and use the term in your next English conversation about security. The quiz checks your vocabulary, and the flashcards keep the terms in rotation. See you in the next Technical English episode of the Audio Lab!"}],"provenance":{"id":"audiolab-audio-eng10-presenting-project","origin":"proprio","category":"Micro-learning em áudio (CyberDimension Audio Lab)","title":"Audio Lab — presenting-project","source":"CyberDimension Academy","license":"Conteúdo autoral da CyberDimension Academy; uso de estudo dentro da plataforma.","usage":"Episódio de vocabulário técnico de cibersegurança em inglês, com pronúncia, tradução e exemplos autorais da CyberDimension Academy."}},
  {"id":"audio-eng11-phishing-describing", audioUrl: "/manus-storage/ep32-threat-intel-osint_1549cfdc.wav","series":"english","title":"phishing-describing","description":"Descrevendo ataques de phishing em inglês","duration":"9min00s","topics":["inglês técnico","vocabulário de cibersegurança","spoofed","suspicious","link","attachment","sender","impersonate","urgency","credibility","report","quarantine"],"transcript":[{"speaker":"Ana","text":"Welcome to the CyberDimension Audio Lab, Technical English series. Eu sou a Ana, e hoje praticamos inglês técnico para cibersegurança. O tema do episódio: Descrevendo ataques de phishing em inglês. Let's warm up with ten essential terms."},{"speaker":"Rafael","text":"Cada termo com pronúncia e exemplo, Ana. O primeiro da lista de hoje:"},{"speaker":"Ana","text":"Number one: \"spoofed\", pronounced \"spúufd\". In Brazilian Portuguese, we say \"falsificado\". Example sentence: \"The email came from a spoofed domain.\"."},{"speaker":"Rafael","text":"Repeating: \"spoofed\", \"The email came from a spoofed domain.\". The pronunciation trick: O 'oo' soa como 'úu'.."},{"speaker":"Ana","text":"Number one: \"suspicious\", pronounced \"sasspíshass\". In Brazilian Portuguese, we say \"suspeito\". Example sentence: \"The attachment looked suspicious to the user.\"."},{"speaker":"Rafael","text":"Repeating: \"suspicious\", \"The attachment looked suspicious to the user.\". The pronunciation trick: Acento em 'pí' e dois 'ss'.."},{"speaker":"Ana","text":"Number one: \"link\", pronounced \"link\". In Brazilian Portuguese, we say \"link, enlace\". Example sentence: \"Do not click the link before verifying the sender.\"."},{"speaker":"Rafael","text":"Repeating: \"link\", \"Do not click the link before verifying the sender.\". The pronunciation trick: Simples: 'link' mesmo.."},{"speaker":"Ana","text":"Number one: \"attachment\", pronounced \"atétchment\". In Brazilian Portuguese, we say \"anexo\". Example sentence: \"The invoice attachment contained malware.\"."},{"speaker":"Rafael","text":"Repeating: \"attachment\", \"The invoice attachment contained malware.\". The pronunciation trick: O 'ch' soa como 'tch'.."},{"speaker":"Ana","text":"Number one: \"sender\", pronounced \"sénder\". In Brazilian Portuguese, we say \"remetente\". Example sentence: \"The sender address was slightly misspelled.\"."},{"speaker":"Rafael","text":"Repeating: \"sender\", \"The sender address was slightly misspelled.\". The pronunciation trick: O 'der' é suave.."},{"speaker":"Ana","text":"Now the second half of our ten-term list:"},{"speaker":"Ana","text":"\"impersonate\", pronounced \"impérssonêit\". We translate as \"se passar por\". Example: \"The attacker impersonated the it department.\"."},{"speaker":"Rafael","text":"\"impersonate\". Acento em 'pér'.."},{"speaker":"Ana","text":"\"urgency\", pronounced \"érdjensi\". We translate as \"urgência\". Example: \"Phishing often creates a false sense of urgency.\"."},{"speaker":"Rafael","text":"\"urgency\". O 'dg' soa como 'dj'.."},{"speaker":"Ana","text":"\"credibility\", pronounced \"credibíliti\". We translate as \"credibilidade\". Example: \"Typos reduce the credibility of the message.\"."},{"speaker":"Rafael","text":"\"credibility\". Acento em 'bí'.."},{"speaker":"Ana","text":"\"report\", pronounced \"riport\". We translate as \"reportar, denunciar\". Example: \"Report suspicious emails using the report button.\"."},{"speaker":"Rafael","text":"\"report\". O 'r' final é suave.."},{"speaker":"Ana","text":"\"quarantine\", pronounced \"kuárantin\". We translate as \"quarentena\". Example: \"The mailbox moved the message to quarantine.\"."},{"speaker":"Rafael","text":"\"quarantine\". Acento em 'rán'.."},{"speaker":"Rafael","text":"Practice time, Ana. Descrição de incidente: 'The spoofed email impersonated hr with urgent language, but the user reported it and the quarantine caught the attachment.' — Seis termos em uma narrativa completa!"},{"speaker":"Ana","text":"Great dialog, Rafael. Remember: listen, repeat, and use the term in your next English conversation about security. The quiz checks your vocabulary, and the flashcards keep the terms in rotation. See you in the next Technical English episode of the Audio Lab!"}],"provenance":{"id":"audiolab-audio-eng11-phishing-describing","origin":"proprio","category":"Micro-learning em áudio (CyberDimension Audio Lab)","title":"Audio Lab — phishing-describing","source":"CyberDimension Academy","license":"Conteúdo autoral da CyberDimension Academy; uso de estudo dentro da plataforma.","usage":"Episódio de vocabulário técnico de cibersegurança em inglês, com pronúncia, tradução e exemplos autorais da CyberDimension Academy."}},
  {"id":"audio-eng12-logs-monitoring", audioUrl: "/manus-storage/ep04-security-operations_90f7cff1.wav","series":"english","title":"logs-monitoring","description":"Inglês para logs e monitoramento","duration":"9min00s","topics":["inglês técnico","vocabulário de cibersegurança","log","timestamp","event","source ip","destination","baseline","anomaly","correlation","dashboard","alerting"],"transcript":[{"speaker":"Ana","text":"Welcome to the CyberDimension Audio Lab, Technical English series. Eu sou a Ana, e hoje praticamos inglês técnico para cibersegurança. O tema do episódio: Inglês para logs e monitoramento. Let's warm up with ten essential terms."},{"speaker":"Rafael","text":"Cada termo com pronúncia e exemplo, Ana. O primeiro da lista de hoje:"},{"speaker":"Ana","text":"Number one: \"log\", pronounced \"lóg\". In Brazilian Portuguese, we say \"log, registro\". Example sentence: \"The log shows three failed attempts before success.\"."},{"speaker":"Rafael","text":"Repeating: \"log\", \"The log shows three failed attempts before success.\". The pronunciation trick: O 'o' tem som de 'ó'.."},{"speaker":"Ana","text":"Number one: \"timestamp\", pronounced \"táimstamp\". In Brazilian Portuguese, we say \"marca temporal\". Example sentence: \"The timestamp confirms the login time.\"."},{"speaker":"Rafael","text":"Repeating: \"timestamp\", \"The timestamp confirms the login time.\". The pronunciation trick: Compound: time + stamp.."},{"speaker":"Ana","text":"Number one: \"event\", pronounced \"ivént\". In Brazilian Portuguese, we say \"evento\". Example sentence: \"Event id 4625 means a failed login.\"."},{"speaker":"Rafael","text":"Repeating: \"event\", \"Event id 4625 means a failed login.\". The pronunciation trick: O 'e' inicial soa como 'i'.."},{"speaker":"Ana","text":"Number one: \"source ip\", pronounced \"sôurs ái-pi\". In Brazilian Portuguese, we say \"ip de origem\". Example sentence: \"The source ip belongs to an unknown region.\"."},{"speaker":"Rafael","text":"Repeating: \"source ip\", \"The source ip belongs to an unknown region.\". The pronunciation trick: Letreio 'i-pê'.."},{"speaker":"Ana","text":"Number one: \"destination\", pronounced \"déstinêishon\". In Brazilian Portuguese, we say \"destino\". Example sentence: \"The destination port is the database server.\"."},{"speaker":"Rafael","text":"Repeating: \"destination\", \"The destination port is the database server.\". The pronunciation trick: Acento em 'têi'.."},{"speaker":"Ana","text":"Now the second half of our ten-term list:"},{"speaker":"Ana","text":"\"baseline\", pronounced \"bêislain\". We translate as \"linha de base\". Example: \"This traffic exceeds our normal baseline.\"."},{"speaker":"Rafael","text":"\"baseline\". Compound: base + line.."},{"speaker":"Ana","text":"\"anomaly\", pronounced \"enómeli\". We translate as \"anomalia\". Example: \"The anomaly detection flagged the pattern.\"."},{"speaker":"Rafael","text":"\"anomaly\". Acento em 'nó'.."},{"speaker":"Ana","text":"\"correlation\", pronounced \"korelêishon\". We translate as \"correlação\". Example: \"Log correlation connects the events into a story.\"."},{"speaker":"Rafael","text":"\"correlation\". 'tion' vira 'shon'.."},{"speaker":"Ana","text":"\"dashboard\", pronounced \"déxbord\". We translate as \"painel de controle\". Example: \"The dashboard shows alerts by severity.\"."},{"speaker":"Rafael","text":"\"dashboard\". O 'd' final é leve.."},{"speaker":"Ana","text":"\"alerting\", pronounced \"alértin\". We translate as \"geração de alertas\". Example: \"Alerting rules notify the on-call analyst.\"."},{"speaker":"Rafael","text":"\"alerting\". Do verbo 'to alert'.."},{"speaker":"Rafael","text":"Practice time, Ana. Frase de SOC: 'The timestamp and source ip stood out against the baseline; the correlation rule triggered an alert on the dashboard.' — Cinco termos de monitoramento!"},{"speaker":"Ana","text":"Great dialog, Rafael. Remember: listen, repeat, and use the term in your next English conversation about security. The quiz checks your vocabulary, and the flashcards keep the terms in rotation. See you in the next Technical English episode of the Audio Lab!"}],"provenance":{"id":"audiolab-audio-eng12-logs-monitoring","origin":"proprio","category":"Micro-learning em áudio (CyberDimension Audio Lab)","title":"Audio Lab — logs-monitoring","source":"CyberDimension Academy","license":"Conteúdo autoral da CyberDimension Academy; uso de estudo dentro da plataforma.","usage":"Episódio de vocabulário técnico de cibersegurança em inglês, com pronúncia, tradução e exemplos autorais da CyberDimension Academy."}},
  {"id":"audio-eng13-passwords-identity", audioUrl: "/manus-storage/ep13-identidade-acesso_f601c4de.wav","series":"english","title":"passwords-identity","description":"Identity vocabulary: senhas e autenticação","duration":"9min00s","topics":["inglês técnico","vocabulário de cibersegurança","password policy","mfa","otp","biometrics","passphrase","dictionary attack","brute force","lockout","session","credential"],"transcript":[{"speaker":"Ana","text":"Welcome to the CyberDimension Audio Lab, Technical English series. Eu sou a Ana, e hoje praticamos inglês técnico para cibersegurança. O tema do episódio: Identity vocabulary: senhas e autenticação. Let's warm up with ten essential terms."},{"speaker":"Rafael","text":"Cada termo com pronúncia e exemplo, Ana. O primeiro da lista de hoje:"},{"speaker":"Ana","text":"Number one: \"password policy\", pronounced \"pássuérde pólessi\". In Brazilian Portuguese, we say \"política de senhas\". Example sentence: \"The password policy requires twelve characters.\"."},{"speaker":"Rafael","text":"Repeating: \"password policy\", \"The password policy requires twelve characters.\". The pronunciation trick: Duas palavras com acentos em 'páss' e 'pó'.."},{"speaker":"Ana","text":"Number one: \"mfa\", pronounced \"ém-éf-êi\". In Brazilian Portuguese, we say \"autenticação multifator\". Example sentence: \"Mfa is mandatory for admin accounts.\"."},{"speaker":"Rafael","text":"Repeating: \"mfa\", \"Mfa is mandatory for admin accounts.\". The pronunciation trick: Letreio em inglês: M-F-A.."},{"speaker":"Ana","text":"Number one: \"otp\", pronounced \"ou-ti-pi\". In Brazilian Portuguese, we say \"senha de uso único\". Example sentence: \"The otp expires in thirty seconds.\"."},{"speaker":"Rafael","text":"Repeating: \"otp\", \"The otp expires in thirty seconds.\". The pronunciation trick: Letreio: O-T-P.."},{"speaker":"Ana","text":"Number one: \"biometrics\", pronounced \"baiométriks\". In Brazilian Portuguese, we say \"biometria\". Example sentence: \"Biometrics includes fingerprint and face recognition.\"."},{"speaker":"Rafael","text":"Repeating: \"biometrics\", \"Biometrics includes fingerprint and face recognition.\". The pronunciation trick: Acento em 'trí'.."},{"speaker":"Ana","text":"Number one: \"passphrase\", pronounced \"pésfrêis\". In Brazilian Portuguese, we say \"frase-senha\". Example sentence: \"A passphrase like 'correct horse battery staple' is strong.\"."},{"speaker":"Rafael","text":"Repeating: \"passphrase\", \"A passphrase like 'correct horse battery staple' is strong.\". The pronunciation trick: Compound: pass + phrase.."},{"speaker":"Ana","text":"Now the second half of our ten-term list:"},{"speaker":"Ana","text":"\"dictionary attack\", pronounced \"díxoneri aték\". We translate as \"ataque de dicionário\". Example: \"The dictionary attack tried common words first.\"."},{"speaker":"Rafael","text":"\"dictionary attack\". O 'ction' soa como 'xoneri'.."},{"speaker":"Ana","text":"\"brute force\", pronounced \"brút fórs\". We translate as \"força bruta\". Example: \"Brute force tries every combination until it works.\"."},{"speaker":"Rafael","text":"\"brute force\". Duas palavras fortes e curtas.."},{"speaker":"Ana","text":"\"lockout\", pronounced \"lókaut\". We translate as \"bloqueio de conta\". Example: \"Five failed attempts trigger an account lockout.\"."},{"speaker":"Rafael","text":"\"lockout\". Compound: lock + out.."},{"speaker":"Ana","text":"\"session\", pronounced \"séxion\". We translate as \"sessão\". Example: \"The session expires after thirty minutes of inactivity.\"."},{"speaker":"Rafael","text":"\"session\". O 'ss' soa como 'x'.."},{"speaker":"Ana","text":"\"credential\", pronounced \"kridénxel\". We translate as \"credencial\". Example: \"Credential stuffing reuses leaked passwords.\"."},{"speaker":"Rafael","text":"\"credential\". Acento em 'dén'.."},{"speaker":"Rafael","text":"Practice time, Ana. Frase de identidade: 'The password policy enforces mfa and lockout after failed attempts, blocking dictionary and brute force attacks.' — Cinco termos de autenticação!"},{"speaker":"Ana","text":"Great dialog, Rafael. Remember: listen, repeat, and use the term in your next English conversation about security. The quiz checks your vocabulary, and the flashcards keep the terms in rotation. See you in the next Technical English episode of the Audio Lab!"}],"provenance":{"id":"audiolab-audio-eng13-passwords-identity","origin":"proprio","category":"Micro-learning em áudio (CyberDimension Audio Lab)","title":"Audio Lab — passwords-identity","source":"CyberDimension Academy","license":"Conteúdo autoral da CyberDimension Academy; uso de estudo dentro da plataforma.","usage":"Episódio de vocabulário técnico de cibersegurança em inglês, com pronúncia, tradução e exemplos autorais da CyberDimension Academy."}},
  {"id":"audio-eng14-network-attacks-english", audioUrl: "/manus-storage/ep32-threat-intel-osint_1549cfdc.wav","series":"english","title":"network-attacks-english","description":"Network attacks vocabulary","duration":"9min00s","topics":["inglês técnico","vocabulário de cibersegurança","dos attack","intercept","eavesdropping","spoofing","mitm","arp poisoning","vlan","dmz","nat","port scan"],"transcript":[{"speaker":"Ana","text":"Welcome to the CyberDimension Audio Lab, Technical English series. Eu sou a Ana, e hoje praticamos inglês técnico para cibersegurança. O tema do episódio: Network attacks vocabulary. Let's warm up with ten essential terms."},{"speaker":"Rafael","text":"Cada termo com pronúncia e exemplo, Ana. O primeiro da lista de hoje:"},{"speaker":"Ana","text":"Number one: \"dos attack\", pronounced \"di-ou-és aték\". In Brazilian Portuguese, we say \"ataque de negação de serviço\". Example sentence: \"The dos attack flooded the web server with traffic.\"."},{"speaker":"Rafael","text":"Repeating: \"dos attack\", \"The dos attack flooded the web server with traffic.\". The pronunciation trick: Letreio: D-O-S.."},{"speaker":"Ana","text":"Number one: \"intercept\", pronounced \"intercépt\". In Brazilian Portuguese, we say \"interceptar\". Example sentence: \"The attacker tried to intercept the session cookies.\"."},{"speaker":"Rafael","text":"Repeating: \"intercept\", \"The attacker tried to intercept the session cookies.\". The pronunciation trick: Acento em 'cépt'.."},{"speaker":"Ana","text":"Number one: \"eavesdropping\", pronounced \"ívzdrópin\". In Brazilian Portuguese, we say \"escuta clandestina\". Example sentence: \"Unencrypted wifi enables eavesdropping.\"."},{"speaker":"Rafael","text":"Repeating: \"eavesdropping\", \"Unencrypted wifi enables eavesdropping.\". The pronunciation trick: Do verbo 'to eavesdrop'.."},{"speaker":"Ana","text":"Number one: \"spoofing\", pronounced \"spúufin\". In Brazilian Portuguese, we say \"falsificação\". Example sentence: \"Ip spoofing hides the attacker's real address.\"."},{"speaker":"Rafael","text":"Repeating: \"spoofing\", \"Ip spoofing hides the attacker's real address.\". The pronunciation trick: O 'oo' como 'úu'.."},{"speaker":"Ana","text":"Number one: \"mitm\", pronounced \"mí-tu-mí\". In Brazilian Portuguese, we say \"ataque homem-no-meio\". Example sentence: \"A mitm attacker sits between the user and the server.\"."},{"speaker":"Rafael","text":"Repeating: \"mitm\", \"A mitm attacker sits between the user and the server.\". The pronunciation trick: Man-in-the-middle: mitm.."},{"speaker":"Ana","text":"Now the second half of our ten-term list:"},{"speaker":"Ana","text":"\"arp poisoning\", pronounced \"ár-pi pôizn-in\". We translate as \"envenenamento de arp\". Example: \"Arp poisoning redirects traffic to the attacker.\"."},{"speaker":"Rafael","text":"\"arp poisoning\". Letreio: A-R-P.."},{"speaker":"Ana","text":"\"vlan\", pronounced \"vi-lén\". We translate as \"rede local virtual\". Example: \"The vlan isolates guest devices from the office.\"."},{"speaker":"Rafael","text":"\"vlan\". Letreio: V-L-A-N.."},{"speaker":"Ana","text":"\"dmz\", pronounced \"di-ém-zí\". We translate as \"zona desmilitarizada\". Example: \"Public servers live in the dmz.\"."},{"speaker":"Rafael","text":"\"dmz\". Letreio: D-M-Z.."},{"speaker":"Ana","text":"\"nat\", pronounced \"nét\". We translate as \"tradução de endereços\". Example: \"Nat maps internal addresses to a single public ip.\"."},{"speaker":"Rafael","text":"\"nat\". Letreio: N-A-T.."},{"speaker":"Ana","text":"\"port scan\", pronounced \"pórt scén\". We translate as \"varredura de portas\". Example: \"The port scan revealed open services on the target.\"."},{"speaker":"Rafael","text":"\"port scan\". Compound: port + scan.."},{"speaker":"Rafael","text":"Practice time, Ana. Descrição técnica: 'The mitm attacker used arp poisoning to intercept traffic after a port scan revealed the dmz servers behind nat.' — Mitm, arp, intercept, port scan e dmz!"},{"speaker":"Ana","text":"Great dialog, Rafael. Remember: listen, repeat, and use the term in your next English conversation about security. The quiz checks your vocabulary, and the flashcards keep the terms in rotation. See you in the next Technical English episode of the Audio Lab!"}],"provenance":{"id":"audiolab-audio-eng14-network-attacks-english","origin":"proprio","category":"Micro-learning em áudio (CyberDimension Audio Lab)","title":"Audio Lab — network-attacks-english","source":"CyberDimension Academy","license":"Conteúdo autoral da CyberDimension Academy; uso de estudo dentro da plataforma.","usage":"Episódio de vocabulário técnico de cibersegurança em inglês, com pronúncia, tradução e exemplos autorais da CyberDimension Academy."}},
  {"id":"audio-eng15-incident-briefing", audioUrl: "/manus-storage/ep04-security-operations_90f7cff1.wav","series":"english","title":"incident-briefing","description":"Briefing de incidente em inglês","duration":"9min00s","topics":["inglês técnico","vocabulário de cibersegurança","status update","affected systems","contained","remediated","investigation","evidence","impact assessment","next steps","eta","postmortem"],"transcript":[{"speaker":"Ana","text":"Welcome to the CyberDimension Audio Lab, Technical English series. Eu sou a Ana, e hoje praticamos inglês técnico para cibersegurança. O tema do episódio: Briefing de incidente em inglês. Let's warm up with ten essential terms."},{"speaker":"Rafael","text":"Cada termo com pronúncia e exemplo, Ana. O primeiro da lista de hoje:"},{"speaker":"Ana","text":"Number one: \"status update\", pronounced \"stétess ápdeit\". In Brazilian Portuguese, we say \"atualização de status\". Example sentence: \"Here is the status update on the ongoing incident.\"."},{"speaker":"Rafael","text":"Repeating: \"status update\", \"Here is the status update on the ongoing incident.\". The pronunciation trick: Compound comum em reuniões.."},{"speaker":"Ana","text":"Number one: \"affected systems\", pronounced \"afékted sístems\". In Brazilian Portuguese, we say \"sistemas afetados\". Example sentence: \"The affected systems are two web servers and the database.\"."},{"speaker":"Rafael","text":"Repeating: \"affected systems\", \"The affected systems are two web servers and the database.\". The pronunciation trick: O 'ed' final como 't'.."},{"speaker":"Ana","text":"Number one: \"contained\", pronounced \"kântêind\". In Brazilian Portuguese, we say \"contido\". Example sentence: \"The threat is contained and no longer spreading.\"."},{"speaker":"Rafael","text":"Repeating: \"contained\", \"The threat is contained and no longer spreading.\". The pronunciation trick: Do verbo 'to contain'.."},{"speaker":"Ana","text":"Number one: \"remediated\", pronounced \"remidêited\". In Brazilian Portuguese, we say \"remediado\". Example sentence: \"The root cause is remediated with a hotfix.\"."},{"speaker":"Rafael","text":"Repeating: \"remediated\", \"The root cause is remediated with a hotfix.\". The pronunciation trick: Acento em 'mêi'.."},{"speaker":"Ana","text":"Number one: \"investigation\", pronounced \"invéssstigêishon\". In Brazilian Portuguese, we say \"investigação\". Example sentence: \"The investigation is still in progress.\"."},{"speaker":"Rafael","text":"Repeating: \"investigation\", \"The investigation is still in progress.\". The pronunciation trick: 'tion' vira 'shon'.."},{"speaker":"Ana","text":"Now the second half of our ten-term list:"},{"speaker":"Ana","text":"\"evidence\", pronounced \"évidenss\". We translate as \"evidência\". Example: \"We preserved the evidence for further analysis.\"."},{"speaker":"Rafael","text":"\"evidence\". O 'c' soa como 'ss'.."},{"speaker":"Ana","text":"\"impact assessment\", pronounced \"ímpékt aséssment\". We translate as \"avaliação de impacto\". Example: \"The impact assessment shows limited data exposure.\"."},{"speaker":"Rafael","text":"\"impact assessment\". Duas palavras técnicas.."},{"speaker":"Ana","text":"\"next steps\", pronounced \"nékst stéps\". We translate as \"próximos passos\". Example: \"The next steps are patching and user notification.\"."},{"speaker":"Rafael","text":"\"next steps\". Ritmo em duas palavras.."},{"speaker":"Ana","text":"\"eta\", pronounced \"i-ti-êi\". We translate as \"previsão de conclusão\". Example: \"The eta for full restoration is six hours.\"."},{"speaker":"Rafael","text":"\"eta\". Letreio: E-T-A.."},{"speaker":"Ana","text":"\"postmortem\", pronounced \"pôustmórtrem\". We translate as \"análise pós-incidente\". Example: \"The postmortem is scheduled for next monday.\"."},{"speaker":"Rafael","text":"\"postmortem\". Do latim, após o incidente.."},{"speaker":"Rafael","text":"Practice time, Ana. Briefing modelo: 'Status update: the incident is contained, affected systems are remediated, and the next steps are in the postmortem.' — Cinco termos de briefing executivo!"},{"speaker":"Ana","text":"Great dialog, Rafael. Remember: listen, repeat, and use the term in your next English conversation about security. The quiz checks your vocabulary, and the flashcards keep the terms in rotation. See you in the next Technical English episode of the Audio Lab!"}],"provenance":{"id":"audiolab-audio-eng15-incident-briefing","origin":"proprio","category":"Micro-learning em áudio (CyberDimension Audio Lab)","title":"Audio Lab — incident-briefing","source":"CyberDimension Academy","license":"Conteúdo autoral da CyberDimension Academy; uso de estudo dentro da plataforma.","usage":"Episódio de vocabulário técnico de cibersegurança em inglês, com pronúncia, tradução e exemplos autorais da CyberDimension Academy."}},
  {"id":"audio-eng16-report-writing", audioUrl: "/manus-storage/ep69-network-security-interview_54014d2f.wav","series":"english","title":"report-writing","description":"Writing security reports in english","duration":"9min00s","topics":["inglês técnico","vocabulário de cibersegurança","executive summary","finding","recommendation","severity level","risk rating","appendix","methodology","conclusion","confidential","attachment"],"transcript":[{"speaker":"Ana","text":"Welcome to the CyberDimension Audio Lab, Technical English series. Eu sou a Ana, e hoje praticamos inglês técnico para cibersegurança. O tema do episódio: Writing security reports in english. Let's warm up with ten essential terms."},{"speaker":"Rafael","text":"Cada termo com pronúncia e exemplo, Ana. O primeiro da lista de hoje:"},{"speaker":"Ana","text":"Number one: \"executive summary\", pronounced \"egzékiutiv sâmeri\". In Brazilian Portuguese, we say \"resumo executivo\". Example sentence: \"The executive summary highlights the key findings.\"."},{"speaker":"Rafael","text":"Repeating: \"executive summary\", \"The executive summary highlights the key findings.\". The pronunciation trick: Acento em 'zé'.."},{"speaker":"Ana","text":"Number one: \"finding\", pronounced \"fáindin\". In Brazilian Portuguese, we say \"achado\". Example sentence: \"Each finding includes severity and remediation.\"."},{"speaker":"Rafael","text":"Repeating: \"finding\", \"Each finding includes severity and remediation.\". The pronunciation trick: Do verbo 'to find'.."},{"speaker":"Ana","text":"Number one: \"recommendation\", pronounced \"rekomendêishon\". In Brazilian Portuguese, we say \"recomendação\". Example sentence: \"The recommendation is to enforce mfa everywhere.\"."},{"speaker":"Rafael","text":"Repeating: \"recommendation\", \"The recommendation is to enforce mfa everywhere.\". The pronunciation trick: 'tion' vira 'shon'.."},{"speaker":"Ana","text":"Number one: \"severity level\", pronounced \"sivérati lévél\". In Brazilian Portuguese, we say \"nível de severidade\". Example sentence: \"The severity level follows the cvss score.\"."},{"speaker":"Rafael","text":"Repeating: \"severity level\", \"The severity level follows the cvss score.\". The pronunciation trick: Acento em 'vé' e 'lê'.."},{"speaker":"Ana","text":"Number one: \"risk rating\", pronounced \"rísk réitin\". In Brazilian Portuguese, we say \"classificação de risco\". Example sentence: \"The risk rating combines likelihood and impact.\"."},{"speaker":"Rafael","text":"Repeating: \"risk rating\", \"The risk rating combines likelihood and impact.\". The pronunciation trick: Duas palavras com 'i' longo.."},{"speaker":"Ana","text":"Now the second half of our ten-term list:"},{"speaker":"Ana","text":"\"appendix\", pronounced \"apéndiks\". We translate as \"apêndice\". Example: \"Technical details are in the appendix.\"."},{"speaker":"Rafael","text":"\"appendix\". O 'x' final como 'ks'.."},{"speaker":"Ana","text":"\"methodology\", pronounced \"metodólodji\". We translate as \"metodologia\". Example: \"The methodology follows owasp guidelines.\"."},{"speaker":"Rafael","text":"\"methodology\". Acento em 'ló'.."},{"speaker":"Ana","text":"\"conclusion\", pronounced \"konklújun\". We translate as \"conclusão\". Example: \"In conclusion, the system is mostly secure.\"."},{"speaker":"Rafael","text":"\"conclusion\". 'sion' vira 'jun'.."},{"speaker":"Ana","text":"\"confidential\", pronounced \"konfidénxel\". We translate as \"confidencial\". Example: \"The report is marked confidential.\"."},{"speaker":"Rafael","text":"\"confidential\". Acento em 'dén'.."},{"speaker":"Ana","text":"\"attachment\", pronounced \"atétchment\". We translate as \"anexo\". Example: \"Screenshots are included in the attachment.\"."},{"speaker":"Rafael","text":"\"attachment\". O 'ch' como 'tch'.."},{"speaker":"Rafael","text":"Practice time, Ana. Frase de relatório: 'The executive summary lists five findings by severity level, with recommendations in the appendix.' — Executiva, achados, severidade e apêndice!"},{"speaker":"Ana","text":"Great dialog, Rafael. Remember: listen, repeat, and use the term in your next English conversation about security. The quiz checks your vocabulary, and the flashcards keep the terms in rotation. See you in the next Technical English episode of the Audio Lab!"}],"provenance":{"id":"audiolab-audio-eng16-report-writing","origin":"proprio","category":"Micro-learning em áudio (CyberDimension Audio Lab)","title":"Audio Lab — report-writing","source":"CyberDimension Academy","license":"Conteúdo autoral da CyberDimension Academy; uso de estudo dentro da plataforma.","usage":"Episódio de vocabulário técnico de cibersegurança em inglês, com pronúncia, tradução e exemplos autorais da CyberDimension Academy."}},
  {"id":"audio-eng17-asking-for-help", audioUrl: "/manus-storage/ep48-carreira-cyber_bf9810f1.wav","series":"english","title":"asking-for-help","description":"Asking for help in english","duration":"9min00s","topics":["inglês técnico","vocabulário de cibersegurança","could you","would you mind","i am stuck","walk me through","i see","let me double-check","makes sense","i appreciate","no worries","sound good"],"transcript":[{"speaker":"Ana","text":"Welcome to the CyberDimension Audio Lab, Technical English series. Eu sou a Ana, e hoje praticamos inglês técnico para cibersegurança. O tema do episódio: Asking for help in english. Let's warm up with ten essential terms."},{"speaker":"Rafael","text":"Cada termo com pronúncia e exemplo, Ana. O primeiro da lista de hoje:"},{"speaker":"Ana","text":"Number one: \"could you\", pronounced \"kúd iú\". In Brazilian Portuguese, we say \"você poderia\". Example sentence: \"Could you help me review this alert?\"."},{"speaker":"Rafael","text":"Repeating: \"could you\", \"Could you help me review this alert?\". The pronunciation trick: Formal e educado.."},{"speaker":"Ana","text":"Number one: \"would you mind\", pronounced \"uúd iú máind\". In Brazilian Portuguese, we say \"você se importaria\". Example sentence: \"Would you mind checking this log with me?\"."},{"speaker":"Rafael","text":"Repeating: \"would you mind\", \"Would you mind checking this log with me?\". The pronunciation trick: Seguido de verbo com -ing.."},{"speaker":"Ana","text":"Number one: \"i am stuck\", pronounced \"ái ém sták\". In Brazilian Portuguese, we say \"estou travado\". Example sentence: \"I am stuck on the privilege escalation step.\"."},{"speaker":"Rafael","text":"Repeating: \"i am stuck\", \"I am stuck on the privilege escalation step.\". The pronunciation trick: Direto e comum entre técnicos.."},{"speaker":"Ana","text":"Number one: \"walk me through\", pronounced \"uók mi frú\". In Brazilian Portuguese, we say \"me explique passo a passo\". Example sentence: \"Can you walk me through the detection rule?\"."},{"speaker":"Rafael","text":"Repeating: \"walk me through\", \"Can you walk me through the detection rule?\". The pronunciation trick: Expressão idiomática útil.."},{"speaker":"Ana","text":"Number one: \"i see\", pronounced \"ái sí\". In Brazilian Portuguese, we say \"entendi\". Example sentence: \"I see, so the false positive came from the scanner.\"."},{"speaker":"Rafael","text":"Repeating: \"i see\", \"I see, so the false positive came from the scanner.\". The pronunciation trick: Curto e confirma entendimento.."},{"speaker":"Ana","text":"Now the second half of our ten-term list:"},{"speaker":"Ana","text":"\"let me double-check\", pronounced \"lét mi dâbol-tchék\". We translate as \"deixe-me verificar de novo\". Example: \"Let me double-check the timeline before the meeting.\"."},{"speaker":"Rafael","text":"\"let me double-check\". Profissional e cuidadoso.."},{"speaker":"Ana","text":"\"makes sense\", pronounced \"mêiks séns\". We translate as \"faz sentido\". Example: \"That makes sense; the correlation rule needs tuning.\"."},{"speaker":"Rafael","text":"\"makes sense\". Confirma concordância.."},{"speaker":"Ana","text":"\"i appreciate\", pronounced \"ái apríxiêit\". We translate as \"eu agradeço\". Example: \"I appreciate your help with the investigation.\"."},{"speaker":"Rafael","text":"\"i appreciate\". Formal e caloroso.."},{"speaker":"Ana","text":"\"no worries\", pronounced \"nôu uériz\". We translate as \"sem problemas\". Example: \"No worries, we will fix the rule together.\"."},{"speaker":"Rafael","text":"\"no worries\". Informal e acolhedor.."},{"speaker":"Ana","text":"\"sound good\", pronounced \"sáund gúd\". We translate as \"parece bom, combinado\". Example: \"Meeting at two pm? Sound good.\"."},{"speaker":"Rafael","text":"\"sound good\". Fechamento rápido de acordo.."},{"speaker":"Rafael","text":"Practice time, Ana. Diálogo de pedido de ajuda: 'Could you walk me through this alert? I am stuck on the correlation. — Sure, let me double-check the logs. — Makes sense, i appreciate it!'"},{"speaker":"Ana","text":"Great dialog, Rafael. Remember: listen, repeat, and use the term in your next English conversation about security. The quiz checks your vocabulary, and the flashcards keep the terms in rotation. See you in the next Technical English episode of the Audio Lab!"}],"provenance":{"id":"audiolab-audio-eng17-asking-for-help","origin":"proprio","category":"Micro-learning em áudio (CyberDimension Audio Lab)","title":"Audio Lab — asking-for-help","source":"CyberDimension Academy","license":"Conteúdo autoral da CyberDimension Academy; uso de estudo dentro da plataforma.","usage":"Episódio de vocabulário técnico de cibersegurança em inglês, com pronúncia, tradução e exemplos autorais da CyberDimension Academy."}},
  {"id":"audio-eng18-remote-team", audioUrl: "/manus-storage/ep48-carreira-cyber_bf9810f1.wav","series":"english","title":"remote-team","description":"Working with remote international teams","duration":"9min00s","topics":["inglês técnico","vocabulário de cibersegurança","async","time zone","overlap","handoff","availability","follow-up","clarify","misunderstanding","document","standup"],"transcript":[{"speaker":"Ana","text":"Welcome to the CyberDimension Audio Lab, Technical English series. Eu sou a Ana, e hoje praticamos inglês técnico para cibersegurança. O tema do episódio: Working with remote international teams. Let's warm up with ten essential terms."},{"speaker":"Rafael","text":"Cada termo com pronúncia e exemplo, Ana. O primeiro da lista de hoje:"},{"speaker":"Ana","text":"Number one: \"async\", pronounced \"êissink\". In Brazilian Portuguese, we say \"assíncrono\". Example sentence: \"We work async across three time zones.\"."},{"speaker":"Rafael","text":"Repeating: \"async\", \"We work async across three time zones.\". The pronunciation trick: Abreviação de asynchronous.."},{"speaker":"Ana","text":"Number one: \"time zone\", pronounced \"táim zôn\". In Brazilian Portuguese, we say \"fuso horário\". Example sentence: \"Schedule the call considering each time zone.\"."},{"speaker":"Rafael","text":"Repeating: \"time zone\", \"Schedule the call considering each time zone.\". The pronunciation trick: Compound: time + zone.."},{"speaker":"Ana","text":"Number one: \"overlap\", pronounced \"ôuverlép\". In Brazilian Portuguese, we say \"sobreposição de horários\". Example sentence: \"Our overlap is only two hours a day.\"."},{"speaker":"Rafael","text":"Repeating: \"overlap\", \"Our overlap is only two hours a day.\". The pronunciation trick: Acento na segunda parte.."},{"speaker":"Ana","text":"Number one: \"handoff\", pronounced \"héndof\". In Brazilian Portuguese, we say \"passagem de trabalho\". Example sentence: \"The handoff to the asia team happens at five pm.\"."},{"speaker":"Rafael","text":"Repeating: \"handoff\", \"The handoff to the asia team happens at five pm.\". The pronunciation trick: Compound: hand + off.."},{"speaker":"Ana","text":"Number one: \"availability\", pronounced \"aveilabíliti\". In Brazilian Portuguese, we say \"disponibilidade\". Example sentence: \"Update your availability on the shared calendar.\"."},{"speaker":"Rafael","text":"Repeating: \"availability\", \"Update your availability on the shared calendar.\". The pronunciation trick: Acento em 'bí'.."},{"speaker":"Ana","text":"Now the second half of our ten-term list:"},{"speaker":"Ana","text":"\"follow-up\", pronounced \"fólo-ap\". We translate as \"acompanhamento\". Example: \"The follow-up meeting is tomorrow.\"."},{"speaker":"Rafael","text":"\"follow-up\". Compound com hífen.."},{"speaker":"Ana","text":"\"clarify\", pronounced \"klérifai\". We translate as \"esclarecer\". Example: \"Let me clarify the requirements before starting.\"."},{"speaker":"Rafael","text":"\"clarify\". Acento em 'rí'.."},{"speaker":"Ana","text":"\"misunderstanding\", pronounced \"misandersténdin\". We translate as \"mal-entendido\". Example: \"The time difference caused a small misunderstanding.\"."},{"speaker":"Rafael","text":"\"misunderstanding\". Palavra longa, ritmo constante.."},{"speaker":"Ana","text":"\"document\", pronounced \"dókiument\". We translate as \"documentar\". Example: \"Document every decision for the async team.\"."},{"speaker":"Rafael","text":"\"document\". Verbo com acento em 'dó'.."},{"speaker":"Ana","text":"\"standup\", pronounced \"sténdâp\". We translate as \"reunião diária rápida\". Example: \"The daily standup keeps everyone aligned.\"."},{"speaker":"Rafael","text":"\"standup\". Do inglês 'stand up meeting'.."},{"speaker":"Rafael","text":"Practice time, Ana. Frase de time global: 'With limited overlap, we rely on async work, clear handoffs and documented decisions.' — Overlap, async, handoff e document!"},{"speaker":"Ana","text":"Great dialog, Rafael. Remember: listen, repeat, and use the term in your next English conversation about security. The quiz checks your vocabulary, and the flashcards keep the terms in rotation. See you in the next Technical English episode of the Audio Lab!"}],"provenance":{"id":"audiolab-audio-eng18-remote-team","origin":"proprio","category":"Micro-learning em áudio (CyberDimension Audio Lab)","title":"Audio Lab — remote-team","source":"CyberDimension Academy","license":"Conteúdo autoral da CyberDimension Academy; uso de estudo dentro da plataforma.","usage":"Episódio de vocabulário técnico de cibersegurança em inglês, com pronúncia, tradução e exemplos autorais da CyberDimension Academy."}},
  {"id":"audio-eng19-explaining-to-nontech", audioUrl: "/manus-storage/ep69-network-security-interview_54014d2f.wav","series":"english","title":"explaining-to-nontech","description":"Explaining security to non-technical audiences","duration":"9min00s","topics":["inglês técnico","vocabulário de cibersegurança","in simple terms","risk","protect","safe","scam","lock","warn","trusted","double-check","peace of mind"],"transcript":[{"speaker":"Ana","text":"Welcome to the CyberDimension Audio Lab, Technical English series. Eu sou a Ana, e hoje praticamos inglês técnico para cibersegurança. O tema do episódio: Explaining security to non-technical audiences. Let's warm up with ten essential terms."},{"speaker":"Rafael","text":"Cada termo com pronúncia e exemplo, Ana. O primeiro da lista de hoje:"},{"speaker":"Ana","text":"Number one: \"in simple terms\", pronounced \"in sím-pol térms\". In Brazilian Portuguese, we say \"em termos simples\". Example sentence: \"In simple terms, the lock was changed after the break-in.\"."},{"speaker":"Rafael","text":"Repeating: \"in simple terms\", \"In simple terms, the lock was changed after the break-in.\". The pronunciation trick: Expressão para simplificar.."},{"speaker":"Ana","text":"Number one: \"risk\", pronounced \"rísk\". In Brazilian Portuguese, we say \"risco\". Example sentence: \"The risk is low if we update the software.\"."},{"speaker":"Rafael","text":"Repeating: \"risk\", \"The risk is low if we update the software.\". The pronunciation trick: Curto e direto.."},{"speaker":"Ana","text":"Number one: \"protect\", pronounced \"prôtékt\". In Brazilian Portuguese, we say \"proteger\". Example sentence: \"This update protects your accounts from fraud.\"."},{"speaker":"Rafael","text":"Repeating: \"protect\", \"This update protects your accounts from fraud.\". The pronunciation trick: O 'ct' final é suave.."},{"speaker":"Ana","text":"Number one: \"safe\", pronounced \"sêif\". In Brazilian Portuguese, we say \"seguro\". Example sentence: \"Your data stays safe with encryption.\"."},{"speaker":"Rafael","text":"Repeating: \"safe\", \"Your data stays safe with encryption.\". The pronunciation trick: O 'a' longo como 'êi'.."},{"speaker":"Ana","text":"Number one: \"scam\", pronounced \"scém\". In Brazilian Portuguese, we say \"golpe\". Example sentence: \"Never share codes with anyone; it may be a scam.\"."},{"speaker":"Rafael","text":"Repeating: \"scam\", \"Never share codes with anyone; it may be a scam.\". The pronunciation trick: O 'sc' soa como 'sk'.."},{"speaker":"Ana","text":"Now the second half of our ten-term list:"},{"speaker":"Ana","text":"\"lock\", pronounced \"lók\". We translate as \"bloquear\". Example: \"We will lock the account to protect it.\"."},{"speaker":"Rafael","text":"\"lock\". Simples e direto.."},{"speaker":"Ana","text":"\"warn\", pronounced \"uórn\". We translate as \"avisar\". Example: \"We warn users about suspicious messages.\"."},{"speaker":"Rafael","text":"\"warn\". O 'w' inicial aspirado.."},{"speaker":"Ana","text":"\"trusted\", pronounced \"trâsted\". We translate as \"confiável\". Example: \"Only use links from trusted sources.\"."},{"speaker":"Rafael","text":"\"trusted\". O 'ed' final como 't'.."},{"speaker":"Ana","text":"\"double-check\", pronounced \"dâbol-tchék\". We translate as \"conferir de novo\". Example: \"Double-check the sender before sending money.\"."},{"speaker":"Rafael","text":"\"double-check\". Imperativo prático.."},{"speaker":"Ana","text":"\"peace of mind\", pronounced \"pís ôv máind\". We translate as \"tranquilidade\". Example: \"Mfa gives you peace of mind online.\"."},{"speaker":"Rafael","text":"\"peace of mind\". Expressão idiomática.."},{"speaker":"Rafael","text":"Practice time, Ana. Explicação leiga: 'In simple terms, the scam tries to steal your password, so we lock the account, warn the users and keep the data safe.' — Simples, direto e correto!"},{"speaker":"Ana","text":"Great dialog, Rafael. Remember: listen, repeat, and use the term in your next English conversation about security. The quiz checks your vocabulary, and the flashcards keep the terms in rotation. See you in the next Technical English episode of the Audio Lab!"}],"provenance":{"id":"audiolab-audio-eng19-explaining-to-nontech","origin":"proprio","category":"Micro-learning em áudio (CyberDimension Audio Lab)","title":"Audio Lab — explaining-to-nontech","source":"CyberDimension Academy","license":"Conteúdo autoral da CyberDimension Academy; uso de estudo dentro da plataforma.","usage":"Episódio de vocabulário técnico de cibersegurança em inglês, com pronúncia, tradução e exemplos autorais da CyberDimension Academy."}},
  {"id":"audio-eng20-career-pitch-english", audioUrl: "/manus-storage/ep48-carreira-cyber_bf9810f1.wav","series":"english","title":"career-pitch-english","description":"Career pitch: your security story in english","duration":"9min00s","topics":["inglês técnico","vocabulário de cibersegurança","passion","journey","motivated","opportunity","contribute","growth","mindset","hands-on","eager","next chapter"],"transcript":[{"speaker":"Ana","text":"Welcome to the CyberDimension Audio Lab, Technical English series. Eu sou a Ana, e hoje praticamos inglês técnico para cibersegurança. O tema do episódio: Career pitch: your security story in english. Let's warm up with ten essential terms."},{"speaker":"Rafael","text":"Cada termo com pronúncia e exemplo, Ana. O primeiro da lista de hoje:"},{"speaker":"Ana","text":"Number one: \"passion\", pronounced \"péxon\". In Brazilian Portuguese, we say \"paixão\". Example sentence: \"My passion for security started with a first ctf.\"."},{"speaker":"Rafael","text":"Repeating: \"passion\", \"My passion for security started with a first ctf.\". The pronunciation trick: O 'ss' soa como 'x'.."},{"speaker":"Ana","text":"Number one: \"journey\", pronounced \"djérni\". In Brazilian Portuguese, we say \"jornada\". Example sentence: \"My journey began with help desk and grew into soc analysis.\"."},{"speaker":"Rafael","text":"Repeating: \"journey\", \"My journey began with help desk and grew into soc analysis.\". The pronunciation trick: O 'j' como 'dj'.."},{"speaker":"Ana","text":"Number one: \"motivated\", pronounced \"môtivêited\". In Brazilian Portuguese, we say \"motivado\". Example sentence: \"I am motivated by solving real security problems.\"."},{"speaker":"Rafael","text":"Repeating: \"motivated\", \"I am motivated by solving real security problems.\". The pronunciation trick: Acento em 'vei'.."},{"speaker":"Ana","text":"Number one: \"opportunity\", pronounced \"óportiúneti\". In Brazilian Portuguese, we say \"oportunidade\". Example sentence: \"This role is a great opportunity to apply my skills.\"."},{"speaker":"Rafael","text":"Repeating: \"opportunity\", \"This role is a great opportunity to apply my skills.\". The pronunciation trick: Acento em 'tú'.."},{"speaker":"Ana","text":"Number one: \"contribute\", pronounced \"kântriúbiut\". In Brazilian Portuguese, we say \"contribuir\". Example sentence: \"I want to contribute to a stronger security posture.\"."},{"speaker":"Rafael","text":"Repeating: \"contribute\", \"I want to contribute to a stronger security posture.\". The pronunciation trick: Acento em 'biú'.."},{"speaker":"Ana","text":"Now the second half of our ten-term list:"},{"speaker":"Ana","text":"\"growth\", pronounced \"gróuth\". We translate as \"crescimento\". Example: \"I value continuous growth and feedback.\"."},{"speaker":"Rafael","text":"\"growth\". O 'ow' como 'ôu'.."},{"speaker":"Ana","text":"\"mindset\", pronounced \"máindset\". We translate as \"mentalidade\". Example: \"The defender mindset looks for the unexpected.\"."},{"speaker":"Rafael","text":"\"mindset\". Compound: mind + set.."},{"speaker":"Ana","text":"\"hands-on\", pronounced \"hénds-on\". We translate as \"prático\". Example: \"My hands-on labs cover forensics and siem.\"."},{"speaker":"Rafael","text":"\"hands-on\". Adjetivo prático comum em vagas.."},{"speaker":"Ana","text":"\"eager\", pronounced \"íger\". We translate as \"ansioso por, ávido\". Example: \"I am eager to learn cloud security.\"."},{"speaker":"Rafael","text":"\"eager\". O 'g' soa como 'dj'.."},{"speaker":"Ana","text":"\"next chapter\", pronounced \"nékst tchépter\". We translate as \"próximo capítulo\". Example: \"I see this academy as my next chapter.\"."},{"speaker":"Rafael","text":"\"next chapter\". Metafórico e memorável.."},{"speaker":"Rafael","text":"Practice time, Ana. Pitch final: 'My passion started with a first ctf, and this hands-on journey motivates me to contribute to a team with a defender mindset.' — Seis termos de carreira em uma história!"},{"speaker":"Ana","text":"Great dialog, Rafael. Remember: listen, repeat, and use the term in your next English conversation about security. The quiz checks your vocabulary, and the flashcards keep the terms in rotation. See you in the next Technical English episode of the Audio Lab!"}],"provenance":{"id":"audiolab-audio-eng20-career-pitch-english","origin":"proprio","category":"Micro-learning em áudio (CyberDimension Audio Lab)","title":"Audio Lab — career-pitch-english","source":"CyberDimension Academy","license":"Conteúdo autoral da CyberDimension Academy; uso de estudo dentro da plataforma.","usage":"Episódio de vocabulário técnico de cibersegurança em inglês, com pronúncia, tradução e exemplos autorais da CyberDimension Academy."}},
] as const;
